def stage_channel_plan(record):
    channel = str(record.get('channel', ''))
    allowed = sorted({str(item) for item in record.get('allowed_channels', [])})
    return {
        'channel': channel,
        'allowed': allowed,
    }

def finalize_channel_plan(staged):
    channel = staged.get('channel', '')
    allowed = staged.get('allowed', [])
    allowed_now = channel in allowed
    return {
        'decision': 'allowed' if allowed_now else 'blocked',
        'channel': channel,
        'matched_by': 'exact_allowlist' if allowed_now else None,
        'checked_count': len(allowed),
    }
